use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,path::Path,process::{Command,Stdio}};
fn hash(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn main(){let r=Path::new("/home/ubuntu/src/zopro-perf-work/trace-one-square175");let z=Path::new("/home/ubuntu/src/zk-tools/zopro");let d=z.join("docs/benchmarks/2026-10-30-trace-one-square175");let s=z.join("docs/benchmarks/2026-10-29-current-cpu-summary");let pins=read(r.join("pins.json"));let mut frozen=BTreeMap::new();let mut retained=0;
 for(p,h)in pins.as_object().unwrap(){let bytes=if p==s.join("README.md").to_str().unwrap()||p==s.join("data.json").to_str().unwrap(){let rel=Path::new(p).strip_prefix(z.parent().unwrap()).unwrap();let out=Command::new("git").arg("show").arg(format!("7f33f0ff70:{}",rel.display())).output().unwrap();assert!(out.status.success());frozen.insert(p.clone(),json!({"sha256":hash(&out.stdout),"utf8":String::from_utf8(out.stdout.clone()).unwrap(),"source_commit":"7f33f0ff70aa79631f2a92d94c17ffd05799f803"}));retained+=1;out.stdout}else{fs::read(p).unwrap()};assert_eq!(hash(&bytes),h.as_str().unwrap());}assert_eq!(retained,2);
 let bytes=serde_json::to_vec(&frozen).unwrap();let tmp=r.join("inherited-summary.json");fs::write(&tmp,&bytes).unwrap();let out=d.join("artifacts/inherited-summary.json.gz");assert!(Command::new("gzip").args(["-n","-c"]).arg(&tmp).stdout(Stdio::from(fs::File::create(&out).unwrap())).status().unwrap().success());let back=Command::new("gzip").args(["-dc"]).arg(&out).output().unwrap();assert!(back.status.success());assert_eq!(back.stdout,bytes);
 let previous:Value=serde_json::from_str(frozen[s.join("data.json").to_str().unwrap()]["utf8"].as_str().unwrap()).unwrap();let current=read(s.join("data.json"));assert_eq!(previous["rows"],current["rows"]);assert_eq!(current["accepted_original8_CPU10x"],0);assert_eq!(current["historical_distinct_Gnark_ledger"],23971);let analysis=read(r.join("analysis.json"));assert_eq!(analysis,read(d.join("artifacts/analysis.json")));assert_eq!(analysis["cells"],current["latest_trace_one_square_component"]["cells"]);assert_eq!(analysis["comparisons"],current["latest_trace_one_square_component"]["comparisons"]);assert_eq!(analysis["gate_passed"],false);assert_eq!(analysis["failed_checks"].as_array().unwrap().len(),2);
 let sources=read(s.join("source-hashes.json"));for(p,h)in sources.as_object().unwrap(){assert_eq!(hash(&fs::read(z.join(p)).unwrap()),h.as_str().unwrap());}let manifest=read(z.join("docs/benchmarks/2026-10-29-balanced-kh-adoption/artifacts/production-source-manifest.json"));for(p,h)in manifest["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(&fs::read(z.join(p)).unwrap()),h.as_str().unwrap());}
 let mut links=0;for base in[&d,&s]{let text=fs::read_to_string(base.join("README.md")).unwrap();for tail in text.split("](").skip(1){let link=tail.split(')').next().unwrap();assert!(base.join(link).is_file(),"missing {link}");links+=1;}}
 assert_eq!(read(r.join("runs/result.json"))["steps"].as_array().unwrap().len(),796);assert_eq!(read(r.join("rows.json")).as_array().unwrap().len(),776);assert!(analysis["profiles"].as_object().unwrap().values().all(|v|v["attribution_qualified"]==true&&v["zero_lost"]==true));assert!(analysis["counters"].as_object().unwrap().values().all(|v|v["qualified"]==true));
 println!("{}",json!({"capture_pins_verified":pins.as_object().unwrap().len(),"documentary_pins_reconstructed_exactly_from_capture_commit":2,"all_other_pins_match_current_files":true,"summary_source_pins":sources.as_object().unwrap().len(),"production_source_hashes":175,"accepted_local_AWS_rows_unchanged":9,"CPU_Metal_reference_rows_unchanged":8,"links":links,"caller_or_SDK_measurements":0,"proof_ledger":23971,"production_changed":false}));}
